 return AV_axes()+`<polyline points="${p.join(' ')}" fill="none" stroke="${GRN}" stroke-width="5"/><circle cx="${AV_gx(0.275).toFixed(1)}" cy="${AV_gy(60).toFixed(1)}" r="9" fill="${GRN}"/>`
